from fastapi import FastAPI, HTTPException
from pydantic import BaseModel, validator
import joblib
import numpy as np
import pandas as pd
from typing import Optional

# Load model on startup (not on every request)
pipe = joblib.load('models/v1/pipeline.joblib')
feature_names = joblib.load('models/v1/feature_names.joblib')

app = FastAPI(title='ML Model API', version='1.0')

class PredictRequest(BaseModel):
    age: float
    income: float
    tenure_months: int
    num_products: int
    has_credit_card: int

    @validator('age')
    def age_must_be_positive(cls, v):
        if v <= 0:
            raise ValueError('age must be positive')
        return v

class PredictResponse(BaseModel):
    prediction: int
    probability: float
    model_version: str = 'v1'

@app.post('/v1/predict', response_model=PredictResponse)
def predict(req: PredictRequest):
    # Build feature DataFrame in the correct column order
    data = pd.DataFrame([req.dict()], columns=feature_names)

    try:
        pred = int(pipe.predict(data)[0])
        prob = float(pipe.predict_proba(data)[0, 1])
        return PredictResponse(prediction=pred, probability=prob)
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))

@app.get('/health')
def health():
    return {'status': 'ok', 'model': 'v1'}
